from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from app.api.routes import router


app = FastAPI(
    title="JEV vs LLM Guardrail Classifier",
    description="AI-powered guardrail classification and JEV vs LLM comparison",
    version="1.0.0"
)


app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:5173"],
    allow_methods=["*"],
    allow_headers=["*"],
)


app.include_router(router)


@app.get("/")
def root():
    return {
        "message": "JEV vs LLM Guardrail Classifier API",
        "status": "running"
    }


@app.get("/health")
def health():
    return {
        "status": "healthy"
    }

