import UploadPanel from "./UploadPanel";
import ModelDropdown from "./ModelDropdown";
import ResultsTable from "./ResultsTable";
import type { EngineState, LlmResultRow, UploadResponse } from "../types";

interface OtherLlmPanelProps {
  fileInfo: UploadResponse | null;
  onUploaded: (response: UploadResponse) => void;
  hasCategories: boolean;
  model: string;
  onModelChange: (model: string) => void;
  prompt: string;
  onPromptChange: (prompt: string) => void;
  engine: EngineState<LlmResultRow>;
  onRun: () => void;
}

export default function OtherLlmPanel({
  fileInfo,
  onUploaded,
  hasCategories,
  model,
  onModelChange,
  prompt,
  onPromptChange,
  engine,
  onRun,
}: OtherLlmPanelProps) {
  const running = engine.status === "running";
  const canRun = !!fileInfo && hasCategories && !running && model.trim() !== "" && prompt.trim() !== "";

  return (
    <div className="card engine-panel engine-panel-llm">
      <div className="engine-panel-header">
        <span className="status-dot status-dot-llm" />
        <span className="engine-title">General LLM · free-form</span>
        <span className="pill pill-llm">unbounded</span>
      </div>

      <UploadPanel fileInfo={fileInfo} onUploaded={onUploaded} />

      <ModelDropdown value={model} onChange={onModelChange} />

      <div className="field-block">
        <label className="field-label">Context / state / prompt</label>
        <textarea
          className="input textarea"
          placeholder="Should this guardrail be approved? Give a decision and a one-line reason."
          value={prompt}
          onChange={(e) => onPromptChange(e.target.value)}
          rows={4}
        />
      </div>

      <button type="button" className="btn btn-dark" disabled={!canRun} onClick={onRun}>
        {running ? "Running…" : "Run →"}
      </button>

      {engine.error && <p className="error-text">{engine.error}</p>}

      {engine.status === "done" && (
        <p className="muted">
          {engine.results.length} rows classified in {((engine.elapsedMs ?? 0) / 1000).toFixed(1)}s
        </p>
      )}

      <ResultsTable
        rows={engine.results}
        rowKey={(row) => row.GuardrailId}
        emptyText="Run to see results"
        columns={[
          { header: "ID", render: (r) => r.GuardrailId },
          { header: "Rule", render: (r) => r.ShortRule },
          { header: "Category", render: (r) => r.LLM_Category },
        ]}
      />
    </div>
  );
}

export interface ResultsColumn<T> {
  header: string;
  render: (row: T) => React.ReactNode;
}

interface ResultsTableProps<T> {
  rows: T[];
  columns: ResultsColumn<T>[];
  emptyText: string;
  rowKey: (row: T) => string;
}

export default function ResultsTable<T>({
  rows,
  columns,
  emptyText,
  rowKey,
}: ResultsTableProps<T>) {
  if (rows.length === 0) {
    return <p className="muted results-empty">{emptyText}</p>;
  }

  return (
    <div className="results-table-wrap">
      <table className="results-table">
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col.header}>{col.header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={rowKey(row)}>
              {columns.map((col) => (
                <td key={col.header}>{col.render(row)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

:root {
  color-scheme: light;
  --surface-page: #eef1f3;
  --surface-card: #ffffff;
  --surface-field: #f3f5f6;
  --text-primary: #11151a;
  --text-secondary: #5b6472;
  --text-muted: #8b93a0;
  --border: #e2e5e9;
  --gridline: #e6e8eb;
  --series-jev: #159d80;
  --series-jev-dark: #0f7a63;
  --series-jev-track: #d8f1e8;
  --series-llm: #171a21;
  --series-llm-track: #eceef0;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--surface-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

.app-shell {
  max-width: 1280px;
  margin: 0 auto;
  padding: 28px 24px 64px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
}

.app-header-title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.app-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: var(--series-jev);
  color: #ffffff;
  font-weight: 700;
  font-size: 13px;
  flex-shrink: 0;
}

.app-header h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--text-secondary);
  max-width: 640px;
  font-size: 14px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-secondary);
  white-space: nowrap;
  margin-top: 4px;
}

.status-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-muted);
  display: inline-block;
}

.card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 20px;
}

.muted {
  color: var(--text-muted);
  font-size: 13px;
}

.hint-text {
  color: var(--text-muted);
  font-size: 12px;
  margin: 8px 0 0;
}

.error-text {
  color: #d03b3b;
  font-size: 13px;
  margin: 8px 0 0;
}

.section-label {
  font-weight: 600;
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.btn {
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 11px 16px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.btn-primary {
  background: var(--series-jev);
  color: #ffffff;
  width: 100%;
  margin-bottom: 8px;
}

.btn-primary:not(:disabled):hover {
  background: var(--series-jev-dark);
}

.btn-dark {
  background: var(--series-llm);
  color: #ffffff;
  width: 100%;
  margin-bottom: 12px;
}

.btn-outline {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-weight: 500;
}

.btn-link {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  text-decoration: underline;
  padding: 4px 0;
  width: 100%;
  text-align: left;
  font-weight: 400;
  margin-bottom: 12px;
}

.btn-small {
  font-size: 13px;
  padding: 6px 12px;
}

.btn-icon {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 18px;
  line-height: 1;
  padding: 4px 8px;
}

.input {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 11px 14px;
  font-size: 14px;
  font-family: var(--font-mono);
  background: var(--surface-field);
  color: var(--text-primary);
}

.input::placeholder {
  color: var(--text-muted);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

.textarea {
  resize: vertical;
}

.field-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.field-row {
  display: flex;
  gap: 10px;
}

.field-row .field-block {
  flex: 1;
}

.field-label {
  font-size: 13px;
  color: var(--text-secondary);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

.input-button {
  text-align: left;
  cursor: pointer;
  color: var(--text-muted);
  background: var(--surface-field);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

.choice-values-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

@media (max-width: 500px) {
  .choice-values-grid {
    grid-template-columns: 1fr;
  }
}

.choice-value-cell {
  position: relative;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px;
  background: var(--surface-field);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.choice-value-cell .input {
  background: var(--surface-card);
}

.choice-value-remove {
  position: absolute;
  top: 4px;
  right: 6px;
}

.engine-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 860px) {
  .engine-grid {
    grid-template-columns: 1fr;
  }
}

.engine-panel {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.engine-panel-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}

.engine-title {
  font-weight: 700;
  font-size: 16px;
}

.status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
}

.status-dot-jev {
  background: var(--series-jev);
}

.status-dot-llm {
  background: var(--series-llm);
}

.pill {
  border-radius: 999px;
  padding: 3px 12px;
  font-size: 12px;
  font-weight: 500;
  margin-left: auto;
}

.pill-jev {
  background: var(--series-jev-track);
  color: var(--series-jev-dark);
}

.pill-llm {
  background: var(--series-llm-track);
  color: var(--text-secondary);
}

.results-table-wrap {
  overflow-x: auto;
}

.results-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.results-table th,
.results-table td {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--gridline);
  font-variant-numeric: tabular-nums;
}

.results-table th {
  color: var(--text-muted);
  font-weight: 500;
}

.results-empty {
  text-align: center;
  padding: 28px 0;
  background: var(--surface-field);
  border-radius: 12px;
  margin-top: 4px;
}

.comparison-section .section-label {
  font-size: 12px;
}

.comparison-header {
  margin-bottom: 16px;
}

.agreement-banner {
  font-size: 14px;
  margin-bottom: 16px;
}

.meter-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

@media (max-width: 860px) {
  .meter-grid {
    grid-template-columns: 1fr;
  }
}

.meter-tile {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
}

.meter-tile-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
}

.meter-tile-header .muted {
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.04em;
}

.meter-labels,
