import { useState } from "react";
import UploadPanel from "./UploadPanel";
import CategoryEditor from "./CategoryEditor";
import ResultsTable from "./ResultsTable";
import type { Category, EngineState, JevResultRow, UploadResponse } from "../types";

interface JevPanelProps {
  fileInfo: UploadResponse | null;
  onUploaded: (response: UploadResponse) => void;
  categories: Category[];
  onCategoriesChange: (categories: Category[]) => void;
  context: string;
  onContextChange: (context: string) => void;
  engine: EngineState<JevResultRow>;
  onRunPreview: () => Promise<void>;
  onRunFull: () => Promise<void>;
}

export default function JevPanel({
  fileInfo,
  onUploaded,
  categories,
  onCategoriesChange,
  context,
  onContextChange,
  engine,
  onRunPreview,
  onRunFull,
}: JevPanelProps) {
  const [fullRunning, setFullRunning] = useState(false);
  const running = engine.status === "running";
  const hasCategories = categories.some((c) => c.name.trim() !== "");
  const disabled = !fileInfo || !hasCategories;

  async function handleFullRun() {
    setFullRunning(true);
    try {
      await onRunFull();
    } finally {
      setFullRunning(false);
    }
  }

  return (
    <div className="card engine-panel engine-panel-jev">
      <div className="engine-panel-header">
        <span className="status-dot status-dot-jev" />
        <span className="engine-title">Jev · typed Choice</span>
        <span className="pill pill-jev">deterministic</span>
      </div>

      <UploadPanel fileInfo={fileInfo} onUploaded={onUploaded} />

      <div className="field-block">
        <label className="field-label">Context / state</label>
        <input
          className="input"
          placeholder="e.g. audience=HCP, channel=email, market=US"
          value={context}
          onChange={(e) => onContextChange(e.target.value)}
        />
      </div>

      <CategoryEditor categories={categories} onChange={onCategoriesChange} />

      <button
        type="button"
        className="btn btn-primary"
        disabled={disabled || running}
        onClick={onRunPreview}
      >
        {running ? "Running…" : `Run choice →`}
      </button>

      <button
        type="button"
        className="btn btn-link"
        disabled={disabled || running || fullRunning}
        onClick={handleFullRun}
      >
        {fullRunning
          ? "Running full dataset…"
          : `Run full dataset (slow, all rows) →`}
      </button>

      {engine.error && <p className="error-text">{engine.error}</p>}

      {engine.status === "done" && (
        <p className="muted">
          {engine.results.length} rows classified in {((engine.elapsedMs ?? 0) / 1000).toFixed(1)}s
        </p>
      )}

      <ResultsTable
        rows={engine.results}
        rowKey={(row) => row.GuardrailId}
        emptyText="Run to see results"
        columns={[
          { header: "ID", render: (r) => r.GuardrailId },
          { header: "Rule", render: (r) => r.ShortRule },
          { header: "Category", render: (r) => r.JEV_Category },
          {
            header: "Confidence",
            render: (r) => (r.JEV_Confidence != null ? r.JEV_Confidence.toFixed(2) : "—"),
          },
        ]}
      />
    </div>
  );
}

import { useEffect, useState } from "react";
import "./App.css";
import JevPanel from "./components/JevPanel";
import OtherLlmPanel from "./components/OtherLlmPanel";
import ComparisonSection from "./components/ComparisonSection";
import { compare, runJevFull, runJevPreview, runLlmPreview } from "./api/client";
import type {
  Category,
  CompareResponse,
  EngineState,
  JevResultRow,
  LlmResultRow,
  UploadResponse,
} from "./types";

function makeId() {
  return Math.random().toString(36).slice(2, 10);
}

const idleEngine = <T,>(): EngineState<T> => ({ status: "idle", results: [] });

export default function App() {
  const [fileInfo, setFileInfo] = useState<UploadResponse | null>(null);
  const [categories, setCategories] = useState<Category[]>([
    { id: makeId(), name: "", description: "" },
  ]);
  const [context, setContext] = useState("");
  const [previewLimit] = useState(5);

  const [jev, setJev] = useState<EngineState<JevResultRow>>(idleEngine());
  const [llm, setLlm] = useState<EngineState<LlmResultRow>>(idleEngine());

  const [model, setModel] = useState("");
  const [prompt, setPrompt] = useState(
    "Should this guardrail be approved? Give a decision and a one-line reason."
  );

  const [comparing, setComparing] = useState(false);
  const [comparison, setComparison] = useState<CompareResponse | null>(null);
  const [comparisonError, setComparisonError] = useState<string | null>(null);

  const hasCategories = categories.some((c) => c.name.trim() !== "");
  const fileId = fileInfo?.file_id ?? null;

  async function handleJevPreview() {
    if (!fileId) return;
    setJev({ status: "running", results: [] });
    const start = performance.now();
    try {
      const { results } = await runJevPreview(fileId, categories, previewLimit, context);
      setJev({ status: "done", results, elapsedMs: performance.now() - start });
    } catch (err) {
      setJev({
        status: "error",
        results: [],
        error: err instanceof Error ? err.message : "JEV preview failed.",
      });
    }
  }

  async function handleJevFull() {
    if (!fileId) return;
    const start = performance.now();
    try {
      const { results } = await runJevFull(fileId, categories, context);
      setJev({ status: "done", results, elapsedMs: performance.now() - start });
    } catch (err) {
      setJev({
        status: "error",
        results: [],
        error: err instanceof Error ? err.message : "JEV full run failed.",
      });
    }
  }

  async function handleLlmRun() {
    if (!fileId) return;
    setLlm({ status: "running", results: [] });
    const start = performance.now();
    try {
      const { results } = await runLlmPreview(
        fileId,
        categories,
        model,
        prompt,
        previewLimit,
        context
      );
      setLlm({ status: "done", results, elapsedMs: performance.now() - start });
    } catch (err) {
      setLlm({
        status: "error",
        results: [],
        error: err instanceof Error ? err.message : "LLM preview failed.",
      });
    }
  }

  useEffect(() => {
    if (jev.status === "done" && llm.status === "done" && fileId) {
      setComparing(true);
      setComparisonError(null);
      compare(fileId, jev.results, llm.results, model)
        .then(setComparison)
        .catch((err) =>
          setComparisonError(err instanceof Error ? err.message : "Comparison failed.")
        )
        .finally(() => setComparing(false));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [jev.status, llm.status]);

  const statusLabel = comparison ? "Compared" : comparing ? "Comparing" : "Awaiting runs";

  return (
    <div className="app-shell">
      <header className="app-header">
        <div className="app-header-title">
          <span className="app-icon">J</span>
          <div>
            <h1>Jev vs LLM Comparison</h1>
            <p className="subtitle">
              One document, two engines, side by side. Jev returns a constrained
              choice; a general LLM returns free-form text.
            </p>

import type {
  CompareResponse,
  JevResultRow,
  LlmResultRow,
  ModelOption,
  UploadResponse,
} from "../types";

const BASE_URL = import.meta.env.VITE_API_BASE_URL ?? "http://localhost:8000/api";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${BASE_URL}${path}`, init);

  if (!response.ok) {
    let detail = response.statusText;
    try {
      const body = await response.json();
      detail = body.detail ?? detail;
    } catch {
      // response had no JSON body
    }
    throw new Error(detail);
  }

  return response.json() as Promise<T>;
}

function categoriesAsDict(categories: { name: string; description: string }[]) {
  const dict: Record<string, string> = {};
  for (const category of categories) {
    if (category.name.trim()) {
      dict[category.name.trim()] = category.description.trim();
    }
  }
  return dict;
}

export async function uploadFile(file: File): Promise<UploadResponse> {
  const formData = new FormData();
  formData.append("file", file);

  return request<UploadResponse>("/upload", {
    method: "POST",
    body: formData,
  });
}

export async function getModels(): Promise<{ models: ModelOption[] }> {
  return request("/models");
}

export async function getRecommendedModels(): Promise<{ models: ModelOption[] }> {
  return request("/models/recommended");
}

export async function runJevPreview(
  fileId: string,
  categories: { name: string; description: string }[],
  limit: number,
  context: string
): Promise<{ results: JevResultRow[] }> {
  return request(`/classify/${fileId}/preview`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      limit,
      context,
    }),
  });
}

export async function runJevFull(
  fileId: string,
  categories: { name: string; description: string }[],
  context: string
): Promise<{ results: JevResultRow[] }> {
  return request(`/classify/${fileId}/run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      context,
    }),
  });
}

export async function runLlmPreview(
  fileId: string,
  categories: { name: string; description: string }[],
  model: string,
  prompt: string,
  limit: number,
  context: string
): Promise<{ results: LlmResultRow[] }> {
  return request(`/classify/${fileId}/llm-preview`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      model,
      prompt,
      limit,
      context,
    }),
  });
}

export async function compare(
  fileId: string,
  jevResults: JevResultRow[],
  llmResults: LlmResultRow[],
  model: string
): Promise<CompareResponse> {
  return request(`/compare/${fileId}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      jev_results: jevResults,
      llm_results: llmResults,
      model,
    }),
  });
}

export function exportUrl(fileId: string): string {
  return `${BASE_URL}/export/${fileId}`;
}

export interface Category {
  id: string;
  name: string;
  description: string;
}

export interface UploadResponse {
  success: boolean;
  file_id: string;
  original_filename: string;
  file_path: string;
  workbook: {
    filename: string;
    sheet_count: number;
    sheets: Record<string, { rows: number; columns: string[] }>;
  };
  total_guardrails: number;
}

export interface JevUsage {
  input_tokens?: number;
  output_tokens?: number;
  cost?: number;
}

export interface JevResultRow {
  GuardrailId: string;
  ShortRule: string;
  JEV_Category: string;
  JEV_Confidence: number | null;
  JEV_Probabilities?: Record<string, number>;
  JEV_Usage: JevUsage;
}

export interface LlmUsage {
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
  cost?: number;
}

export interface LlmResultRow {
  GuardrailId: string;
  ShortRule: string;
  LLM_Category: string;
  LLM_Usage: LlmUsage;
}

export interface ModelOption {
  id: string;
  name: string;
  provider?: string;
  context_length?: number;
  pricing?: Record<string, unknown>;
}

export interface ComparisonRow {
  GuardrailId: string;
  ShortRule: string;
  JEV_Category: string;
  LLM_Category: string;
  agreement: boolean;
  JEV_Confidence: number | null;
  JEV_Input_Tokens: number;
  JEV_Output_Tokens: number;
  JEV_Cost: number;
  LLM_Input_Tokens: number;
  LLM_Output_Tokens: number;
  LLM_Cost: number;
}

export interface CompareResponse {
  success: boolean;
  file_id: string;
  total_compared: number;
  agreements: number;
  disagreements: number;
  agreement_percentage: number;
  comparisons: ComparisonRow[];
  output_file: string;
}

