  onProgress: (progress: JevRunProgress) => void
): Promise<{
  results: JevResultRow[];
  mode: "normal" | "batch";
  batch_size: number;
  usage_note?: string;
}> {
  const job = await request<{
    job_id: string;
    mode: "normal" | "batch";
    batch_size: number;
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
