  "code": "from typing import Any
import os
import requests
from pathlib import Path
from dotenv import load_dotenv

BASE_DIR = Path(__file__).resolve().parents[3]
SETTINGS_FILE = BASE_DIR / "settings.txt"
load_dotenv(BASE_DIR / ".env")
OPENROUTER_API_URL = "https://openrouter.ai/api/alpha/decisions"
JEV_MODEL = "typesafe/jev-1.13"
MAX_JEV_BATCH_SIZE = 64

def get_jev_settings() -> dict[str, Any]:
    if not SETTINGS_FILE.is_file():
        raise FileNotFoundError(f"JEV settings file not found: {SETTINGS_FILE}")
    settings: dict[str, str] = {}
    for line_number, line in enumerate(SETTINGS_FILE.read_text(encoding="utf-8").splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "=" not in stripped:
            raise ValueError(f"Invalid JEV setting on line {line_number}; expected key=value.")
        key, value = (part.strip() for part in stripped.split("=", 1))
        settings[key.lower()] = value
    mode = settings.get("mode", "").lower()
    if mode not in {"normal", "batch"}:
        raise ValueError("JEV mode in settings.txt must be either 'normal' or 'batch'.")
    try:
        batch_size = int(settings.get("batch_size", ""))
    except ValueError as exc:
        raise ValueError(f"JEV batch_size must be from 1 to {MAX_JEV_BATCH_SIZE}.") from exc
    if not 1 <= batch_size <= MAX_JEV_BATCH_SIZE:
        raise ValueError(f"JEV batch_size must be from 1 to {MAX_JEV_BATCH_SIZE}.")
    return {"mode": mode, "batch_size": batch_size}

def _authorization_headers() -> dict[str, str]:
    api_key = os.getenv("OPENROUTER_API_KEY")
    if not api_key:
        raise ValueError("OPENROUTER_API_KEY is not configured.")
    return {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

def classify_guardrail(guardrail: str, categories: dict) -> dict:
    payload = {"model": JEV_MODEL, "state": guardrail, "questions": {"category": {"type": "choice", "instructions": "Which category best describes this guardrail? Choose exactly one category based on the guardrail's meaning.", "criteria": categories}}}
    response = requests.post(OPENROUTER_API_URL, headers=_authorization_headers(), json=payload, timeout=60)
    response.raise_for_status()
    data = response.json()
    answer = data["answers"]["category"]
    return {"category": answer.get("choice"), "confidence": answer.get("confidence"), "probabilities": answer.get("probabilities"), "usage": data.get("usage", {})}

def classify_guardrails_batch(guardrails: list[dict[str, str]], categories: dict[str, str], context: str) -> dict[str, Any]:
    if not guardrails:
        raise ValueError("A JEV batch must contain at least one guardrail.")
