          onRun={handleLlmRun}
        />
      </div>

      <ComparisonSection
        fileId={fileId}
        jev={jev}
        llm={llm}
        comparing={comparing}
        comparison={comparison}
        comparisonError={comparisonError}
      />
    </div>
  );
}

