// Shown only if the live OpenRouter model list can't be fetched (e.g. network
// policy blocking openrouter.ai), so the dropdown is never empty.
const FALLBACK_MODELS: ModelOption[] = [
  { id: "openai/gpt-6-luna", name: "OpenAI: GPT-6 Luna", provider: "OpenAI (offline list)" },
  { id: "anthropic/claude-sonnet-5", name: "Anthropic: Claude Sonnet 5", provider: "Anthropic (offline list)" },
  { id: "google/gemini-3-pro", name: "Google: Gemini 3 Pro", provider: "Google (offline list)" },
];

export default function ModelDropdown({ value, onChange }: ModelDropdownProps) {
  const [models, setModels] = useState<ModelOption[]>([]);
  const [offline, setOffline] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const recommended = await getRecommendedModels();
        if (cancelled) return;

        if (recommended.models.length > 0) {
          setModels(recommended.models);
          return;
        }

        const all = await getModels();
        if (!cancelled) setModels(all.models);
      } catch (err) {
        if (!cancelled) {
          setModels(FALLBACK_MODELS);
          setOffline(true);
          setError(err instanceof Error ? err.message : "Could not load models.");
        }
      }
    }

    load();
    return () => {
      cancelled = true;
    };
  }, []);

  const grouped = models.reduce<Record<string, ModelOption[]>>((acc, model) => {
    const key = model.provider ?? "Other";
    (acc[key] ??= []).push(model);
    return acc;
  }, {});

  return (
    <div className="field-block">
      <label className="field-label">Model</label>
      <select
        className="input"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      >
        <option value="" disabled>
          Select a model…
        </option>
        {Object.entries(grouped).map(([provider, items]) => (
          <optgroup label={provider} key={provider}>
            {items.map((model) => (
              <option value={model.id} key={model.id}>
                {model.name}
              </option>
            ))}
          </optgroup>
        ))}
      </select>
      {offline && (
        <p className="hint-text">
          Live model list unavailable ({error}) — showing an offline fallback list.
        </p>
      )}
    </div>
  );
}

