                name
                for name in categories
                if name.casefold() == candidate.casefold()
            ),
            None,
        )
        if matching_category:
            category = matching_category

    usage = data.get("usage", {})

    return {
        "category": category,
        "answer": answer,
        "usage": usage
    }

