export async function runLlmFull(
  fileId: string,
  categories: { name: string; description: string }[],
  model: string,
  prompt: string,
  context: string,
  limit: number | null,
  onProgress: (progress: JevRunProgress) => void
): Promise<{ results: LlmResultRow[]; failed: number }> {
  const job = await request<{
    job_id: string;
    status: "queued" | "running";
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
  }>(`/classify/${fileId}/llm-run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      model,
      prompt,
      context,
      limit: limit ?? 0,
    }),
  });

  const reportProgress = (
    status: {
      status: "queued" | "running";
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
    },
    mode: "queued" | "running"
  ) => {
    onProgress({
      status: mode,
      mode: "normal",
      batch_size: 1,
      total_rows: status.total_rows,
      completed: status.completed,
      processed: status.processed,
      failed: status.failed,
    });
  };

  reportProgress(job, "queued");
  while (true) {
    await new Promise((resolve) => window.setTimeout(resolve, 750));
    const status = await request<{
      status: "queued" | "running" | "done" | "error";
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
      job_id: string;
      results?: LlmResultRow[];
      error?: string;
    }>(`/classify/${fileId}/llm-run/${job.job_id}`);

    if (status.status === "queued") {
      reportProgress({ ...status, status: "queued" }, "queued");
      continue;
    }
    if (status.status === "running") {
      reportProgress({ ...status, status: "running" }, "running");
      continue;
    }
    if (status.status === "error") {
      throw new Error(status.error ?? "Full LLM classification failed.");
    }
    return {
      results: status.results ?? [],
      failed: status.failed,
    };
  }
}

