import os
import requests
from pathlib import Path
from dotenv import load_dotenv
from typing import Any

BASE_DIR = Path(__file__).resolve().parents[3]
SETTINGS_FILE = BASE_DIR / "settings.txt"
load_dotenv(BASE_DIR / ".env")

OPENROUTER_API_URL = "https://openrouter.ai/api/alpha/decisions"
JEV_MODEL = "typesafe/jev-1.13"
MAX_JEV_BATCH_SIZE = 64


def get_jev_settings() -> dict[str, Any]:
    if not SETTINGS_FILE.is_file():
        raise FileNotFoundError(
            f"JEV settings file not found: {SETTINGS_FILE}"
        )

    settings: dict[str, str] = {}
    for line_number, line in enumerate(
        SETTINGS_FILE.read_text(encoding="utf-8").splitlines(),
        start=1,
    ):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "=" not in stripped:
            raise ValueError(
                f"Invalid JEV setting on line {line_number}; expected key=value."
            )
        key, value = (part.strip() for part in stripped.split("=", 1))
        settings[key.lower()] = value

    mode = settings.get("mode", "").lower()
    if mode not in {"normal", "batch"}:
        raise ValueError(
            "JEV mode in settings.txt must be either 'normal' or 'batch'."
        )

    try:
        batch_size = int(settings.get("batch_size", ""))
    except ValueError as exc:
        raise ValueError(
            "JEV batch_size in settings.txt must be an integer from 1 to "
            f"{MAX_JEV_BATCH_SIZE}."
        ) from exc

    if not 1 <= batch_size <= MAX_JEV_BATCH_SIZE:
        raise ValueError(
            "JEV batch_size in settings.txt must be from 1 to "
            f"{MAX_JEV_BATCH_SIZE}."
        )

    return {"mode": mode, "batch_size": batch_size}


def _authorization_headers() -> dict[str, str]:
    api_key = os.getenv("OPENROUTER_API_KEY")
    if not api_key:
        raise ValueError("OPENROUTER_API_KEY is not configured.")
    return {
        "Authorization": f"******",
        "Content-Type": "application/json",
    }


def classify_guardrail(guardrail: str, categories: dict) -> dict:
    payload = {
        "model": JEV_MODEL,
        "state": guardrail,
        "questions": {
            "category": {
                "type": "choice",
                "instructions": (
                    "Which category best describes this guardrail? "
                    "Choose exactly one category based on the guardrail's meaning."
                ),
                "criteria": categories
            }
        }
    }

    response = requests.post(
        OPENROUTER_API_URL,
        headers=_authorization_headers(),
        json=payload,
        timeout=60
    )

    response.raise_for_status()

    data = response.json()

    answer = data["answers"]["category"]

    return {
        "category": answer.get("choice"),
        "confidence": answer.get("confidence"),
        "probabilities": answer.get("probabilities"),
        "usage": data.get("usage", {})
    }


def classify_guardrails_batch(
    guardrails: list[dict[str, str]],
    categories: dict[str, str],
    context: str,
) -> dict[str, Any]:
    if not guardrails:
        raise ValueError("A JEV batch must contain at least one guardrail.")

    questions = {
        item["question_id"]: {
            "type": "choice",
            "instructions": (
                "Which category best describes the guardrail in the state "
                f"whose question_id is {item['question_id']}? Choose exactly "
                "one category based on the guardrail's meaning."
            ),
            "criteria": categories,
        }
        for item in guardrails
    }
    payload = {
        "model": JEV_MODEL,
        "state": {
            "context": context,
            "guardrails": [
                {
                    "question_id": item["question_id"],
                    "guardrail_id": item["guardrail_id"],
                    "text": item["text"],
                }
                for item in guardrails
            ],
        },
        "questions": questions,
    }

    response = requests.post(
        OPENROUTER_API_URL,
        headers=_authorization_headers(),
        json=payload,
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    return {
        "answers": data.get("answers", {}),
        "usage": data.get("usage", {}),
    }

export interface Category {
  id: string;
  name: string;
  description: string;
}

export interface UploadResponse {
  success: boolean;
  file_id: string;
  original_filename: string;
  file_path: string;
  workbook: {
    filename: string;
    sheet_count: number;
    sheets: Record<string, { rows: number; columns: string[] }>;
  };
  total_guardrails: number;
}

export interface JevUsage {
  input_tokens?: number;
  output_tokens?: number;
  cost?: number;
}

export interface JevResultRow {
  GuardrailId: string;
  ShortRule: string;
  JEV_Category: string;
  JEV_Confidence: number | null;
  JEV_Probabilities?: Record<string, number>;
  JEV_Usage: JevUsage;
}

export interface LlmUsage {
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
  cost?: number;
}

export interface LlmResultRow {
  GuardrailId: string;
  ShortRule: string;
  LLM_Category: string;
  LLM_Answer?: string;
  LLM_Usage: LlmUsage;
}

export interface LlmFailure {
  GuardrailId: string | number | null;
  error: string;
}

export interface ModelOption {
  id: string;
  name: string;
  provider?: string;
  context_length?: number;
  pricing?: Record<string, unknown>;
}

export interface ComparisonRow {
  GuardrailId: string;
  ShortRule: string;
  JEV_Category: string;
  LLM_Category: string;
  agreement: boolean;
  JEV_Confidence: number | null;
  JEV_Input_Tokens: number;
  JEV_Output_Tokens: number;
  JEV_Cost: number;
  LLM_Input_Tokens: number;
  LLM_Output_Tokens: number;
  LLM_Cost: number;
}

export interface CompareResponse {
  success: boolean;
  file_id: string;
  total_compared: number;
  agreements: number;
  disagreements: number;
  agreement_percentage: number;
  comparisons: ComparisonRow[];
  output_file: string;
}

export type RunStatus = "idle" | "running" | "done" | "error";
export type JevMode = "normal" | "batch";

export interface EngineState<TResult> {
  status: RunStatus;
  results: TResult[];
  error?: string;
  elapsedMs?: number;
  progress?: JevRunProgress;
  runMode?: JevMode;
  batchSize?: number;
  usageNote?: string;
  failedCount?: number;
  failures?: LlmFailure[];
}

export interface JevRunProgress {
  status: "queued" | "running";
  mode: JevMode;
  batch_size: number;
  total_rows: number | null;
  completed: number;
  processed: number;
  failed: number;
}

