import { useEffect, useState } from "react";
import "./App.css";
import JevPanel from "./components/JevPanel";
import OtherLlmPanel from "./components/OtherLlmPanel";
import ComparisonSection from "./components/ComparisonSection";
import { compare, runJevFull, runLlmFull } from "./api/client";
import type {
  Category,
  CompareResponse,
  EngineState,
  JevMode,
  JevResultRow,
  LlmResultRow,
  UploadResponse,
} from "./types";

function makeId() {
  return Math.random().toString(36).slice(2, 10);
}

const idleEngine = <T,>(): EngineState<T> => ({ status: "idle", results: [] });

export default function App() {
  const [fileInfo, setFileInfo] = useState<UploadResponse | null>(null);
  const [categories, setCategories] = useState<Category[]>([
    { id: makeId(), name: "", description: "" },
  ]);
  const [context, setContext] = useState("");

  const [jev, setJev] = useState<EngineState<JevResultRow>>(idleEngine());
  const [llm, setLlm] = useState<EngineState<LlmResultRow>>(idleEngine());

  const [model, setModel] = useState("");
  const [prompt, setPrompt] = useState(
    "Should this guardrail be approved? Give a decision and a one-line reason."
  );

  const [comparing, setComparing] = useState(false);
  const [comparison, setComparison] = useState<CompareResponse | null>(null);
  const [comparisonError, setComparisonError] = useState<string | null>(null);

  const hasCategories = categories.some((c) => c.name.trim() !== "");
  const fileId = fileInfo?.file_id ?? null;

  async function handleJevFull(limit: number | null, selectedMode: JevMode) {
    if (!fileId) return;
    setComparison(null);
    setComparisonError(null);
    setJev({ status: "running", results: [] });
    const start = performance.now();
    try {
      const { results, mode: runMode, batch_size, failed, usage_note } = await runJevFull(
        fileId,
        categories,
        context,
        selectedMode,
        limit,
        (progress) => setJev((current) => ({ ...current, progress }))
      );
      setJev({
        status: "done",
        results,
        elapsedMs: performance.now() - start,
        runMode,
        batchSize: batch_size,
        failedCount: failed,
        usageNote: usage_note,
      });
    } catch (err) {
      setJev({
        status: "error",
        results: [],
        error: err instanceof Error ? err.message : "JEV classification failed.",
      });
    }
  }

  async function handleLlmRun(limit: number | null) {
    if (!fileId || !model.trim()) return;
    setComparison(null);
    setComparisonError(null);
    setLlm({ status: "running", results: [] });
    const start = performance.now();
    try {
      const { results, failed, failures } = await runLlmFull(
        fileId,
        categories,
        model,
        prompt,
        context,
        limit,
        (progress) => setLlm((current) => ({ ...current, progress }))
      );
      setLlm({
        status: "done",
        results,
        elapsedMs: performance.now() - start,
        failedCount: failed,
        failures,
      });
    } catch (err) {
      setLlm({
        status: "error",
        results: [],
        error: err instanceof Error ? err.message : "LLM classification failed.",
      });
    }
  }

  useEffect(() => {
    if (jev.status === "done" && llm.status === "done" && fileId) {
      setComparing(true);
      setComparisonError(null);
      compare(fileId, jev.results, llm.results, model)
        .then(setComparison)
        .catch((err) =>
          setComparisonError(err instanceof Error ? err.message : "Comparison failed.")
        )
        .finally(() => setComparing(false));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [jev.status, llm.status]);

  const statusLabel = comparison ? "Compared" : comparing ? "Comparing" : "Awaiting runs";

  return (
    <div className="app-shell">
      <header className="app-header">
        <div className="app-header-title">
          <span className="app-icon">J</span>
          <div>
            <h1>Jev vs LLM Comparison</h1>
            <p className="subtitle">
              One document, two engines, side by side. Jev returns a constrained
              choice; a general LLM returns free-form text.
            </p>
          </div>
        </div>
        <span className="status-pill">
          <span className="status-pill-dot" /> {statusLabel}
        </span>
      </header>

      <div className="engine-grid">
        <JevPanel
          fileInfo={fileInfo}
          onUploaded={setFileInfo}
          categories={categories}
          onCategoriesChange={setCategories}
          context={context}
          onContextChange={setContext}
          engine={jev}
          onRunFull={handleJevFull}
        />
        <OtherLlmPanel
          fileInfo={fileInfo}
          onUploaded={setFileInfo}
          categories={categories}
          hasCategories={hasCategories}
          model={model}
          onModelChange={setModel}
          prompt={prompt}
          onPromptChange={setPrompt}
          engine={llm}
          onRun={handleLlmRun}
        />
      </div>

      <ComparisonSection
        fileId={fileId}
        jev={jev}
        llm={llm}
        comparing={comparing}
        comparison={comparison}
        comparisonError={comparisonError}
      />
    </div>
  );
}

import type {
  CompareResponse,
  JevResultRow,
  JevMode,
  LlmResultRow,
  ModelOption,
  JevRunProgress,
  LlmFailure,
  UploadResponse,
} from "../types";

const BASE_URL = import.meta.env.VITE_API_BASE_URL ?? "http://localhost:8000/api";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${BASE_URL}${path}`, init);

  if (!response.ok) {
    let detail = response.statusText;
    try {
      const body = await response.json();
      detail = body.detail ?? detail;
    } catch {
      // response had no JSON body
    }
    throw new Error(detail);
  }

  return response.json() as Promise<T>;
}

function categoriesAsDict(categories: { name: string; description: string }[]) {
  const dict: Record<string, string> = {};
  for (const category of categories) {
    if (category.name.trim()) {
      dict[category.name.trim()] = category.description.trim();
    }
  }
  return dict;
}

export async function uploadFile(file: File): Promise<UploadResponse> {
  const formData = new FormData();
  formData.append("file", file);

  return request<UploadResponse>("/upload", {
    method: "POST",
    body: formData,
  });
}

export async function getModels(): Promise<{ models: ModelOption[] }> {
  return request("/models");
}

export async function getRecommendedModels(): Promise<{ models: ModelOption[] }> {
  return request("/models/recommended");
}

export async function runJevPreview(
  fileId: string,
  categories: { name: string; description: string }[],
  limit: number,
  context: string
): Promise<{ results: JevResultRow[] }> {
  return request(`/classify/${fileId}/preview`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      limit,
      context,
    }),
  });
}

export async function runJevFull(
  fileId: string,
  categories: { name: string; description: string }[],
  context: string,
  mode: JevMode,
  limit: number | null,
  onProgress: (progress: JevRunProgress) => void
): Promise<{
  results: JevResultRow[];
  mode: "normal" | "batch";
  batch_size: number;
  failed: number;
  usage_note?: string;
}> {
  const job = await request<{
    job_id: string;
    mode: "normal" | "batch";
    batch_size: number;
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
    status: "queued" | "running";
  }>(`/classify/${fileId}/run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      context,
      mode,
      limit: limit ?? 0,
    }),
  });

  const reportProgress = (status: {
    status: "queued" | "running";
    mode: "normal" | "batch";
    batch_size: number;
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
  }) => {
    onProgress({
      status: status.status,
      mode: status.mode,
      batch_size: status.batch_size,
      total_rows: status.total_rows,
      completed: status.completed,
      processed: status.processed,
      failed: status.failed,
    });
  };

  reportProgress(job);
  while (true) {
    await new Promise((resolve) => window.setTimeout(resolve, 750));
    const status = await request<{
      status: "queued" | "running" | "done" | "error";
      mode: "normal" | "batch";
      batch_size: number;
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
      job_id: string;
      results?: JevResultRow[];
      error?: string;
      usage_note?: string;
    }>(`/classify/${fileId}/run/${job.job_id}`);

    if (status.status === "queued") {
      reportProgress({ ...status, status: "queued" });
      continue;
    }
    if (status.status === "running") {
      reportProgress({ ...status, status: "running" });
      continue;
    }
    if (status.status === "error") {
      throw new Error(status.error ?? "Full JEV classification failed.");
    }
    return {
      results: status.results ?? [],
      mode: status.mode,
      batch_size: status.batch_size,
      failed: status.failed,
      usage_note: status.usage_note,
    };
  }
}

export async function runLlmFull(
  fileId: string,
  categories: { name: string; description: string }[],
  model: string,
  prompt: string,
  context: string,
  limit: number | null,
  onProgress: (progress: JevRunProgress) => void
): Promise<{ results: LlmResultRow[]; failed: number; failures: LlmFailure[] }> {
  const job = await request<{
    job_id: string;
    status: "queued" | "running";
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
  }>(`/classify/${fileId}/llm-run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      model,
      prompt,
      context,
      limit: limit ?? 0,
    }),
  });

  const reportProgress = (
    status: {
      status: "queued" | "running";
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
    },
    mode: "queued" | "running"
  ) => {
    onProgress({
      status: mode,
      mode: "normal",
      batch_size: 1,
      total_rows: status.total_rows,
      completed: status.completed,
      processed: status.processed,
      failed: status.failed,
    });
  };

  reportProgress(job, "queued");
  while (true) {
    await new Promise((resolve) => window.setTimeout(resolve, 750));
    const status = await request<{
      status: "queued" | "running" | "done" | "error";
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
      job_id: string;
      results?: LlmResultRow[];
      failures?: LlmFailure[];
      error?: string;
    }>(`/classify/${fileId}/llm-run/${job.job_id}`);

    if (status.status === "queued") {
      reportProgress({ ...status, status: "queued" }, "queued");
      continue;
    }
    if (status.status === "running") {
      reportProgress({ ...status, status: "running" }, "running");
      continue;
    }
    if (status.status === "error") {
      throw new Error(status.error ?? "Full LLM classification failed.");
    }
    return {
      results: status.results ?? [],
      failed: status.failed,
      failures: status.failures ?? [],
    };
  }
}

export async function runLlmPreview(
  fileId: string,
  categories: { name: string; description: string }[],
  model: string,
  prompt: string,
  limit: number,
  context: string
): Promise<{ results: LlmResultRow[] }> {
  return request(`/classify/${fileId}/llm-preview`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      model,
      prompt,
      limit,
      context,
    }),
  });
}

export async function compare(
  fileId: string,
  jevResults: JevResultRow[],
  llmResults: LlmResultRow[],
  model: string
): Promise<CompareResponse> {
  return request(`/compare/${fileId}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      jev_results: jevResults,
      llm_results: llmResults,
      model,
    }),
  });
}

export function exportUrl(fileId: string): string {
  return `${BASE_URL}/export/${fileId}`;
}

export interface Category {
  id: string;
